insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('energy-leaks-and-refills-audit', 'Energy Leaks and Refills Audit', 'worksheet'::resource_kind, 'The client sorts the week''s activities into those that drain energy and those that restore it.', 'Use it to help a client see where energy goes and plan small refills.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list a typical week''s activities and mark each as a leak, a refill or mixed. Look for one leak to shrink and one refill to protect. Keep the plan small and let the client choose, since a long list of changes tends to stall.', '[{"id": "f0", "type": "textarea", "label": "Activities that drain me"}, {"id": "f1", "type": "textarea", "label": "Activities that refill me"}, {"id": "f2", "type": "textarea", "label": "One leak I could shrink this week"}, {"id": "f3", "type": "textarea", "label": "One refill I will protect and when"}]'::jsonb, array['self-care', 'self-monitoring', 'planning']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('boundary-phrases-rehearsal-planner', 'Boundary Phrases Rehearsal Planner', 'worksheet'::resource_kind, 'The client drafts short boundary phrases and plans when and with whom to try them.', 'Use it to help a client prepare kind, clear ways to say no.', array['Adults', 'Teens']::text[], '30 minutes', 'Invite the client to write phrases in their own voice, then say them aloud in session and adjust the tone. Pick one low-stakes setting for the first try. Check afterward how it felt, not only how the other person reacted.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want a boundary"}, {"id": "f1", "type": "textarea", "label": "What I want to say, in my own words"}, {"id": "f2", "type": "textarea", "label": "Who I will try it with first"}, {"id": "f3", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['boundaries', 'assertiveness', 'communication']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('strengths-in-action-interview-sheet', 'Strengths in Action Interview Sheet', 'worksheet'::resource_kind, 'The client interviews themselves about a past success and names the strengths it shows.', 'Use it to help a client notice strengths they already use.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to pick a time they handled something well, however small, and walk through it with the prompts. Reflect back the strengths you hear and invite them to add their own. Clients who discount wins may need a second example.', '[{"id": "f0", "type": "textarea", "label": "A time I handled something well"}, {"id": "f1", "type": "textarea", "label": "What I did, step by step"}, {"id": "f2", "type": "textarea", "label": "Strengths that showed up"}, {"id": "f3", "type": "textarea", "label": "Where I could use those strengths this week"}]'::jsonb, array['strengths', 'self-esteem', 'reflection']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('transition-time-checklist-builder', 'Transition Time Checklist Builder', 'worksheet'::resource_kind, 'The client builds a short checklist for moving between tasks, places or roles.', 'Use it to give a client a simple routine for the hard moments between activities.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one transition that tends to go badly, such as arriving home or starting work. Have the client choose three to five steps and place the list where they will see it. Revisit in a week and trim any step that does not earn its place.', '[{"id": "f0", "type": "textarea", "label": "A transition that is hard for me"}, {"id": "f1", "type": "textarea", "label": "What usually happens"}, {"id": "f2", "type": "textarea", "label": "Steps for my checklist"}, {"id": "f3", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['routines', 'planning', 'executive skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('wind-down-routine-designer', 'Wind-Down Routine Designer', 'worksheet'::resource_kind, 'The client designs an evening sequence of calming steps with times and cues.', 'Use it to help a client build a gentle routine for the hour before bed.', array['Adults', 'Teens']::text[], '25 minutes', 'Work backward from the client''s usual bedtime and fit in only a few steps they actually like. Note screens, light and cues that signal the end of the day. Treat it as an experiment and adjust together after a week of notes.', '[{"id": "f0", "type": "textarea", "label": "What my evenings look like now"}, {"id": "f1", "type": "textarea", "label": "Steps I would like in my routine"}, {"id": "f2", "type": "textarea", "label": "Times and cues for each step"}, {"id": "f3", "type": "textarea", "label": "What might get in the way and my plan for it"}]'::jsonb, array['sleep', 'routines', 'self-care']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('thought-tally-counter-log', 'Thought Tally Counter Log', 'cbt'::resource_kind, 'The client taps a tally each time a chosen thought shows up and notes the situation.', 'Use it to help a client notice how often and when a thought appears.', array['Adults', 'Teens']::text[], 'One week', 'Pick one thought pattern with the client and agree on a simple way to tally it. The aim is noticing, not stopping the thought. Bring the tally to session and look for times, places and triggers before any challenging work begins.', '[{"id": "f0", "type": "textarea", "label": "The thought I am tallying"}, {"id": "f1", "type": "textarea", "label": "Where and when it showed up most"}, {"id": "f2", "type": "textarea", "label": "What I was doing just before"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the pattern"}]'::jsonb, array['thought records', 'self-monitoring', 'awareness']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('alternative-explanations-brainstorm-page', 'Alternative Explanations Brainstorm Page', 'cbt'::resource_kind, 'The client lists several other ways to explain an event that first looked threatening.', 'Use it to help a client loosen a single fixed explanation.', array['Adults', 'Teens']::text[], '20 minutes', 'Start with one recent event and the client''s first explanation. Ask for as many other explanations as they can think of, including silly ones, then rate how plausible each seems. The goal is flexibility rather than replacing one story with another.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "My first explanation"}, {"id": "f2", "type": "textarea", "label": "Other possible explanations"}, {"id": "f3", "type": "textarea", "label": "Which ones seem most likely and why"}]'::jsonb, array['cognitive restructuring', 'thought records', 'flexibility']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('chore-plus-treat-activity-pairing-plan', 'Chore Plus Treat Activity Pairing Plan', 'cbt'::resource_kind, 'The client pairs a task they avoid with a small pleasant activity and logs how it goes.', 'Use it to help a client make avoided tasks easier to start.', array['Adults', 'Teens']::text[], 'One week', 'Choose a task the client has put off and a small reward that is easy to give themselves. Keep the task small enough to finish. Review mood or energy before and after in the log, and let the client decide what to keep.', '[{"id": "f0", "type": "textarea", "label": "A task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "A small treat I can pair with it"}, {"id": "f2", "type": "textarea", "label": "When I will do both"}, {"id": "f3", "type": "textarea", "label": "How I felt before and after"}]'::jsonb, array['behavioral activation', 'activity scheduling', 'motivation']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('thinking-traps-detective-sheet', 'Thinking Traps Detective Sheet', 'cbt'::resource_kind, 'The client plays detective, spotting common thinking traps in a recent upsetting moment.', 'Use it to help a client name the thinking traps behind a strong reaction.', array['Teens', 'Adults']::text[], '25 minutes', 'Offer a short list of common thinking traps and ask the client to match them to one recent thought. Keep the tone curious and light, since the point is naming a pattern rather than judging it. Follow with one more balanced thought in their words.', '[{"id": "f0", "type": "textarea", "label": "The upsetting moment"}, {"id": "f1", "type": "textarea", "label": "The thought that went with it"}, {"id": "f2", "type": "textarea", "label": "Traps that might be in it"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}]'::jsonb, array['cognitive distortions', 'thought records', 'awareness']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('downward-arrow-meaning-page', 'Downward Arrow Meaning Page', 'cbt'::resource_kind, 'The client follows a worry with the question "and if that were true, what then?" to find the belief underneath.', 'Use it to help a client uncover the belief driving a repeated worry.', array['Adults']::text[], '30 minutes', 'Do this together in session with a moderate worry, not the most painful one. Ask the arrow question gently and stop when the client reaches a belief about themselves or others. Close with something steadying, and return to the belief another day.', '[{"id": "f0", "type": "textarea", "label": "The worry I start with"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean?"}, {"id": "f2", "type": "textarea", "label": "And what would that mean?"}, {"id": "f3", "type": "textarea", "label": "The belief I land on"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend with that belief"}]'::jsonb, array['core beliefs', 'cognitive restructuring', 'reflection']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('floating-leaves-defusion-home-log', 'Floating Leaves Defusion Home Log', 'act'::resource_kind, 'The client practices placing thoughts on leaves floating down a stream and records what they notice.', 'Use it to help a client practice watching thoughts drift by without arguing.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Guide the first practice in session, then let the client use it at home with a short log. Some clients get lost in the imagery or feel they did it wrong; reassure them that noticing the drift away is the practice. Adjust the image if a stream does not suit them.', '[{"id": "f0", "type": "textarea", "label": "When and where I practiced"}, {"id": "f1", "type": "textarea", "label": "Thoughts that came up"}, {"id": "f2", "type": "textarea", "label": "What it was like to watch them go"}, {"id": "f3", "type": "textarea", "label": "What I would change next time"}]'::jsonb, array['defusion', 'mindfulness', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('values-compass-weekly-bearings', 'Values Compass Weekly Bearings', 'act'::resource_kind, 'The client checks direction in a few life areas each week and picks one small step.', 'Use it to help a client link weekly actions to what matters to them.', array['Adults', 'Teens']::text[], '15 minutes weekly', 'Have the client name a few life areas and rate how closely last week matched what they care about, without judging the rating. Then choose one small step. Look out for goals that are really rules in disguise and ask what the step is for.', '[{"id": "f0", "type": "textarea", "label": "Life areas that matter most to me"}, {"id": "f1", "type": "textarea", "label": "How close last week felt"}, {"id": "f2", "type": "textarea", "label": "One small step toward what I care about"}, {"id": "f3", "type": "textarea", "label": "What might pull me off course"}]'::jsonb, array['values', 'committed action', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('silly-voice-defusion-experiment', 'Silly Voice Defusion Experiment', 'act'::resource_kind, 'The client says a sticky thought in a cartoon voice, sung or slowed down, and notes how it feels.', 'Use it to help a client hold a sticky thought more lightly.', array['Adults', 'Teens', 'Children']::text[], '15 minutes', 'Model it first so the client is not alone in feeling silly. The point is not to mock the thought or make it go away but to see it as words. Check with the client that it does not feel dismissive of something painful, and stop if it does.', '[{"id": "f0", "type": "textarea", "label": "The sticky thought"}, {"id": "f1", "type": "textarea", "label": "The voice I tried"}, {"id": "f2", "type": "textarea", "label": "What changed, if anything"}, {"id": "f3", "type": "textarea", "label": "When I might use this"}]'::jsonb, array['defusion', 'playfulness', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('committed-action-mini-contract', 'Committed Action Mini-Contract', 'act'::resource_kind, 'The client writes a small, specific promise to themselves linked to a value, with a plan for obstacles.', 'Use it to help a client turn a value into one doable action.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the action small, observable and tied to a value the client names in their own words. Ask what thoughts or feelings may show up and how they might carry them along. Review without blame, and treat a missed step as information.', '[{"id": "f0", "type": "textarea", "label": "The value behind this action"}, {"id": "f1", "type": "textarea", "label": "What I will do, when and where"}, {"id": "f2", "type": "textarea", "label": "Thoughts and feelings that may show up"}, {"id": "f3", "type": "textarea", "label": "How I will bring them along"}, {"id": "f4", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['committed action', 'values', 'planning']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('observer-self-journal-prompt-page', 'Observer Self Journal Prompt Page', 'act'::resource_kind, 'The client writes from the point of view of the part of them that notices thoughts and feelings.', 'Use it to help a client find a steady place to watch experience from.', array['Adults']::text[], '20 minutes', 'Introduce the idea of the noticing self with a short exercise, then use the prompts. Some clients find this abstract, so offer a concrete image such as the sky and the weather. Keep the pace gentle and let the client set the depth.', '[{"id": "f0", "type": "textarea", "label": "Something I notice in my thoughts today"}, {"id": "f1", "type": "textarea", "label": "Something I notice in my body"}, {"id": "f2", "type": "textarea", "label": "The part of me that is doing the noticing"}, {"id": "f3", "type": "textarea", "label": "What changes when I write from that place"}]'::jsonb, array['self as context', 'mindfulness', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('abc-please-weekly-tracker', 'ABC PLEASE Weekly Tracker', 'dbt'::resource_kind, 'The client tracks the habits that support emotional balance across one week.', 'Use it to help a client see how sleep, movement and routines shape their moods.', array['Adults', 'Teens']::text[], 'One week', 'Walk through the parts of ABC PLEASE and let the client choose two to track. Review the pattern between habits and mood without pushing for perfection. Praise any entry, including a week that went poorly, because honest tracking is the skill.', '[{"id": "f0", "type": "textarea", "label": "The two habits I am tracking"}, {"id": "f1", "type": "textarea", "label": "Daily notes on each"}, {"id": "f2", "type": "textarea", "label": "My mood each day"}, {"id": "f3", "type": "textarea", "label": "What I notice about the link"}, {"id": "f4", "type": "textarea", "label": "One change I will try next week"}]'::jsonb, array['emotion regulation', 'self-care', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('accepting-the-unchangeable-rehearsal-plan', 'Accepting the Unchangeable Rehearsal Plan', 'dbt'::resource_kind, 'The client plans how to use acceptance during an upcoming situation they cannot change.', 'Use it to help a client rehearse accepting what is outside their control.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an upcoming event the client cannot change. Have them describe what they will need to accept, then rehearse the images and self-talk they will use. Practice in session. Acceptance is not approval, so say so out loud.', '[{"id": "f0", "type": "textarea", "label": "The situation I cannot change"}, {"id": "f1", "type": "textarea", "label": "What I need to accept about it"}, {"id": "f2", "type": "textarea", "label": "Words I can say to myself"}, {"id": "f3", "type": "textarea", "label": "Skills I will use if it gets hard"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself afterward"}]'::jsonb, array['radical acceptance', 'distress tolerance', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-experiment-card', 'Opposite Action Experiment Card', 'dbt'::resource_kind, 'The client tries acting opposite to an emotion''s urge when the feeling does not fit the facts.', 'Use it to help a client test an opposite action in a safe, small way.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through one emotion, its urge and an opposite action, and confirm with the client that the feeling does not fit the situation first. Choose a small step and note how the emotion shifts. This works best when practiced fully, not halfway.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its urge"}, {"id": "f1", "type": "textarea", "label": "Does the feeling fit the facts?"}, {"id": "f2", "type": "textarea", "label": "The opposite action I will try"}, {"id": "f3", "type": "textarea", "label": "What happened to the feeling"}]'::jsonb, array['opposite action', 'emotion regulation', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('check-the-facts-walkthrough', 'Check the Facts Walkthrough', 'dbt'::resource_kind, 'The client separates what happened from interpretations and worst-case guesses.', 'Use it to help a client see whether the strength of a feeling matches the facts.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk the steps in order: the event, the interpretations, the assumptions and the threat. Ask the client to describe only what a camera would capture. Then compare the intensity of the feeling to the facts and decide what, if anything, to do.', '[{"id": "f0", "type": "textarea", "label": "What happened, as a camera would see it"}, {"id": "f1", "type": "textarea", "label": "What I told myself about it"}, {"id": "f2", "type": "textarea", "label": "What I am assuming will happen"}, {"id": "f3", "type": "textarea", "label": "Does the size of my feeling fit the facts?"}]'::jsonb, array['check the facts', 'emotion regulation', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('fast-self-respect-check-page', 'FAST Self-Respect Check Page', 'dbt'::resource_kind, 'The client reviews a hard conversation using fair, apologies, stick to values and truthful.', 'Use it to help a client keep self-respect when asking for something.', array['Adults', 'Teens']::text[], '20 minutes', 'Pair this with DEAR MAN when the client worries about losing themselves in a conversation. Rate each FAST item for the planned talk and role-play the weakest. Be alert for clients who over-apologize or hold back the truth to keep the peace.', '[{"id": "f0", "type": "textarea", "label": "The conversation I am preparing for"}, {"id": "f1", "type": "textarea", "label": "Being fair: what that looks like"}, {"id": "f2", "type": "textarea", "label": "Which apologies are not needed"}, {"id": "f3", "type": "textarea", "label": "The value I want to stick to"}, {"id": "f4", "type": "textarea", "label": "What the truthful version sounds like"}]'::jsonb, array['interpersonal effectiveness', 'self-respect', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('evening-appreciation-exchange-ritual', 'Evening Appreciation Exchange Ritual', 'couples'::resource_kind, 'Partners trade one specific appreciation each evening and note how it lands.', 'Use it to help partners build a small daily habit of noticing each other.', array['Couples']::text[], 'Five minutes daily for two weeks', 'Each partner writes one specific thing they appreciated that day and shares it aloud. Coach on being specific rather than general. Partner A and Partner B take turns going first. Review in session what changed and what felt awkward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciated today"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciated today"}, {"id": "f2", "type": "textarea", "label": "Partner A: how it felt to hear it"}, {"id": "f3", "type": "textarea", "label": "Partner B: how it felt to hear it"}]'::jsonb, array['appreciation', 'rituals', 'connection']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('stress-weather-report-for-two', 'Stress Weather Report for Two', 'couples'::resource_kind, 'Partners describe their stress as a daily forecast and agree what each needs from the other.', 'Use it to help partners signal stress and ask for support early.', array['Couples']::text[], '15 minutes', 'Each partner gives today''s forecast, such as clear, cloudy or stormy, and names one thing that would help. The other partner reflects before offering anything. Practice in session, then use it a few times a week at home.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my forecast today"}, {"id": "f1", "type": "textarea", "label": "Partner A: what would help"}, {"id": "f2", "type": "textarea", "label": "Partner B: my forecast today"}, {"id": "f3", "type": "textarea", "label": "Partner B: what would help"}, {"id": "f4", "type": "textarea", "label": "What we will do with this each week"}]'::jsonb, array['stress', 'communication', 'support']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('soft-startup-rehearsal-for-partners', 'Soft Startup Rehearsal for Partners', 'couples'::resource_kind, 'Partners rewrite harsh openings into gentler ones and practice saying them aloud.', 'Use it to help partners begin hard topics in a way that invites listening.', array['Couples']::text[], '30 minutes', 'Each partner brings a recent harsh opening and rewrites it with a feeling, a situation and a request. Practice saying it aloud, with the listening partner reflecting back. Coach on tone as well as words, and swap roles.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a harsh opening I used"}, {"id": "f1", "type": "textarea", "label": "Partner A: my softer version"}, {"id": "f2", "type": "textarea", "label": "Partner B: a harsh opening I used"}, {"id": "f3", "type": "textarea", "label": "Partner B: my softer version"}, {"id": "f4", "type": "textarea", "label": "How the softer versions felt to hear"}]'::jsonb, array['communication', 'soft startup', 'Gottman']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('money-talk-agenda-for-two', 'Money Talk Agenda for Two', 'couples'::resource_kind, 'Partners prepare a short, structured agenda for a calm talk about money.', 'Use it to help partners talk about money with a plan instead of in the heat of a bill.', array['Couples']::text[], '45 minutes', 'Partners fill in their parts separately, then use the agenda for a timed talk. Keep the first agenda short and agree on stopping rules. Money talks often carry history and values, so leave room for what money means to each of them.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what money means to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what money means to me"}, {"id": "f2", "type": "textarea", "label": "One topic we will talk about today"}, {"id": "f3", "type": "textarea", "label": "One decision we will make together"}, {"id": "f4", "type": "textarea", "label": "When we will check in again"}]'::jsonb, array['money', 'communication', 'planning']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('shared-calendar-fairness-walkthrough', 'Shared Calendar Fairness Walkthrough', 'couples'::resource_kind, 'Partners map who carries which tasks over a week and talk about what feels fair.', 'Use it to help partners make shared load visible and renegotiate it kindly.', array['Couples']::text[], '40 minutes', 'Each partner lists the tasks they carry, including invisible planning, then they compare. Look for a gap in perception before a gap in hours. Close with one trade or change to try for two weeks and a time to review.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry"}, {"id": "f2", "type": "textarea", "label": "Where it feels unfair to me"}, {"id": "f3", "type": "textarea", "label": "One trade we will try"}, {"id": "f4", "type": "textarea", "label": "When we will review it"}]'::jsonb, array['household tasks', 'fairness', 'planning']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('build-your-own-feelings-gauge-craft', 'Build-Your-Own Feelings Gauge Craft', 'kids'::resource_kind, 'The child builds a paper thermometer and slides a marker to show how big a feeling is.', 'Use it to help a child show feeling size and pick a calming step to match.', array['Children']::text[], '25 minutes', 'Help the child make a paper thermometer with a sliding marker, and decorate each zone together. Practice moving the marker with different pretend situations. Parents learn the colors and offer the matching calming step at home.', '[{"id": "f0", "type": "textarea", "label": "What the top of my thermometer looks like"}, {"id": "f1", "type": "textarea", "label": "What the middle looks like"}, {"id": "f2", "type": "textarea", "label": "What the bottom looks like"}, {"id": "f3", "type": "textarea", "label": "The calming step I pick for each zone"}]'::jsonb, array['feelings', 'emotion regulation', 'craft']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('breathing-buddy-stuffed-animal-game', 'Breathing Buddy Stuffed Animal Game', 'kids'::resource_kind, 'The child lies down with a stuffed animal on their belly and rocks it with slow breaths.', 'Use it to give a child a playful way to slow down their breathing.', array['Children']::text[], '10 minutes', 'Let the child choose the stuffed animal and name it. Count slow breaths while the animal rises and falls, and try fast breaths first so they can feel the difference. Parents can play at bedtime and join in with their own animal.', '[{"id": "f0", "type": "textarea", "label": "My buddy''s name"}, {"id": "f1", "type": "textarea", "label": "What happened to my buddy when I breathed fast"}, {"id": "f2", "type": "textarea", "label": "What happened when I breathed slow"}, {"id": "f3", "type": "textarea", "label": "When I will play this at home"}]'::jsonb, array['breathing', 'calming', 'play']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('courage-cape-decorating-project', 'Courage Cape Decorating Project', 'kids'::resource_kind, 'The child decorates a cape or bandana with symbols of their brave moments.', 'Use it to help a child remember the times they have been brave.', array['Children']::text[], '30 minutes', 'Provide fabric or paper and markers and let the child draw symbols for times they were brave. Wear the cape together for a short role-play of a hard moment. Parents hang the cape somewhere visible and name brave moments when they notice them.', '[{"id": "f0", "type": "textarea", "label": "A time I was brave"}, {"id": "f1", "type": "textarea", "label": "The symbol I drew for it"}, {"id": "f2", "type": "textarea", "label": "A hard thing I want to try"}, {"id": "f3", "type": "textarea", "label": "Who I will show my cape to"}]'::jsonb, array['courage', 'craft', 'self-esteem']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('emotion-color-painting-page', 'Emotion Color Painting Page', 'kids'::resource_kind, 'The child paints feelings as colors and shapes and talks about what they made.', 'Use it to help a child put feelings into color before putting them into words.', array['Children']::text[], '30 minutes', 'Give the child paints or crayons and invite them to pick a color for each feeling. Ask about the picture rather than interpreting it. Parents can hang it up and use the same color words to check in during the week.', '[{"id": "f0", "type": "textarea", "label": "The feelings I painted"}, {"id": "f1", "type": "textarea", "label": "The color I picked for each one"}, {"id": "f2", "type": "textarea", "label": "Where in my body I feel each one"}, {"id": "f3", "type": "textarea", "label": "Which picture I want to show my grown-up"}]'::jsonb, array['feelings', 'art', 'play']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('calm-corner-pillow-fort-builder', 'Calm Corner Pillow Fort Builder', 'kids'::resource_kind, 'The child designs and builds a small calm-down space with items they choose.', 'Use it to help a child and parent set up a calm space the child owns.', array['Children']::text[], '40 minutes', 'Let the child choose where the corner goes and what fills it, such as pillows, a book and a soft light. Agree with the parent that it is for calming, never a punishment. Practice going there together when everyone is calm.', '[{"id": "f0", "type": "textarea", "label": "What I want in my calm corner"}, {"id": "f1", "type": "textarea", "label": "Where it will go"}, {"id": "f2", "type": "textarea", "label": "How I will know it is time to go there"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do when I am there"}]'::jsonb, array['calming', 'routines', 'parent coaching']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('skill-spinner-showdown', 'Skill Spinner Showdown', 'game'::resource_kind, 'Players spin for a feeling and share a skill they would use, earning points for new ideas.', 'Use it to help a group generate and swap coping ideas in a playful way.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Make a spinner with feelings on it. Rules: spin, name a skill you would use, and score a point for each idea no one has said yet. Go around in turns. Debrief by asking which ideas people want to try and what got in the way.', '[{"id": "f0", "type": "textarea", "label": "The feeling I spun"}, {"id": "f1", "type": "textarea", "label": "The skill I named"}, {"id": "f2", "type": "textarea", "label": "A skill I heard that I want to try"}, {"id": "f3", "type": "textarea", "label": "What I will do this week"}]'::jsonb, array['coping skills', 'group', 'skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('perspective-swap-story-cards', 'Perspective Swap Story Cards', 'game'::resource_kind, 'Players draw a short scene and retell it from the viewpoint of someone else in it.', 'Use it to help players practice seeing a situation through another person''s eyes.', array['Groups', 'Teens', 'Couples']::text[], '30 minutes', 'Write brief everyday scenes on cards. Rules: draw one, retell it as another person in the scene, and the group guesses what that person felt. Take turns. Debrief on how it felt to step into another view, and what made it hard.', '[{"id": "f0", "type": "textarea", "label": "The scene I drew"}, {"id": "f1", "type": "textarea", "label": "Who I retold it as"}, {"id": "f2", "type": "textarea", "label": "What that person might have felt"}, {"id": "f3", "type": "textarea", "label": "What I noticed about my own view"}]'::jsonb, array['perspective taking', 'empathy', 'group']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('strength-guess-round-game', 'Strength Guess Round Game', 'game'::resource_kind, 'Each player shares two true facts and one strength, and the others guess which is the strength.', 'Use it to help a group name strengths in a light, low-pressure way.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: take turns, say three statements with one being a strength, and let others guess. The speaker then tells the story behind the strength. Debrief on how it felt to claim a strength aloud and what others noticed.', '[{"id": "f0", "type": "textarea", "label": "My two true facts"}, {"id": "f1", "type": "textarea", "label": "The strength I shared"}, {"id": "f2", "type": "textarea", "label": "A strength I heard from someone else"}, {"id": "f3", "type": "textarea", "label": "How it felt to say my strength aloud"}]'::jsonb, array['strengths', 'group', 'self-esteem']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('feelings-detective-clue-game', 'Feelings Detective Clue Game', 'game'::resource_kind, 'Players read body and situation clues on cards and guess the hidden feeling.', 'Use it to help players read the clues that point to a feeling.', array['Children', 'Groups', 'Teens']::text[], '25 minutes', 'Prepare cards with clues such as clenched fists or a stomach flutter. Rules: one detective reads clues, the others guess the feeling, and turns rotate. Debrief on which clues showed up in their own bodies and what they do about them.', '[{"id": "f0", "type": "textarea", "label": "A clue that shows up in my body"}, {"id": "f1", "type": "textarea", "label": "The feeling it usually points to"}, {"id": "f2", "type": "textarea", "label": "A time I missed that clue"}, {"id": "f3", "type": "textarea", "label": "What I can do when I notice it"}]'::jsonb, array['feelings', 'awareness', 'group']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('reframe-relay-race', 'Reframe Relay Race', 'game'::resource_kind, 'Teams pass a stuck thought down a line and each player adds a kinder or more balanced version.', 'Use it to help a group practice many ways to rephrase a harsh thought.', array['Groups', 'Teens']::text[], '25 minutes', 'Write harsh-sounding thoughts on cards, with no real names. Rules: each team passes a card down the line, and each player adds a new balanced rewrite before passing it on. Judge for variety. Debrief on which rewrites felt believable.', '[{"id": "f0", "type": "textarea", "label": "A harsh thought I would like to rewrite"}, {"id": "f1", "type": "textarea", "label": "My balanced rewrite"}, {"id": "f2", "type": "textarea", "label": "The rewrite I liked best"}, {"id": "f3", "type": "textarea", "label": "When I could use it"}]'::jsonb, array['cognitive restructuring', 'group', 'skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-check-in-chart', 'Window of Tolerance Check-In Chart', 'worksheet'::resource_kind, 'The client marks where they are in a day: too wound up, steady, or shut down, and what helped.', 'Use it to help a client notice their state and choose a steadying step.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Teach the idea of a steady zone with a simple picture, then have the client mark where they land a few times a day. Keep entries short and focus on what moved them back toward steady. No trauma details are needed or asked for.', '[{"id": "f0", "type": "textarea", "label": "Time and where I was"}, {"id": "f1", "type": "textarea", "label": "Where I was: wound up, steady or shut down"}, {"id": "f2", "type": "textarea", "label": "What helped me move toward steady"}, {"id": "f3", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['PTSD and trauma', 'grounding', 'stabilization', 'self-monitoring']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('safe-now-versus-then-sorting-page', 'Safe Now Versus Then Sorting Page', 'cbt'::resource_kind, 'The client sorts cues in the room into signs of safety now, to help the mind tell the present from the past.', 'Use it to help a client notice present-moment safety without revisiting events.', array['Adults']::text[], '20 minutes', 'Do this in session at a pace that suits the client. They list what they can see, hear and know that shows they are safe now. Stay in the present and do not ask for details of the past. Stop and ground if distress rises.', '[{"id": "f0", "type": "textarea", "label": "Things I can see that show I am safe now"}, {"id": "f1", "type": "textarea", "label": "Things I can hear or feel that show it"}, {"id": "f2", "type": "textarea", "label": "People or places that are safe for me now"}, {"id": "f3", "type": "textarea", "label": "One sentence I can tell myself when I need it"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety', 'stabilization']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('making-room-for-reminders-practice', 'Making Room for Reminders Practice', 'act'::resource_kind, 'The client practices letting reminders be present while choosing a small action that matters to them.', 'Use it to help a client carry hard reminders while still doing what they value.', array['Adults']::text[], '25 minutes', 'Keep the practice present-focused: the client names a recent reminder in a word or two, notices the body, and picks a small values action. Never push for narrative. Go slowly and agree beforehand on a way to pause.', '[{"id": "f0", "type": "textarea", "label": "A reminder that showed up this week, in a few words"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f2", "type": "textarea", "label": "Something that matters to me today"}, {"id": "f3", "type": "textarea", "label": "One small action I can take with the reminder along"}]'::jsonb, array['PTSD and trauma', 'values', 'acceptance', 'pacing']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('safe-container-imagery-practice', 'Safe Container Imagery Practice', 'dbt'::resource_kind, 'The client imagines a strong container for overwhelming material and practices setting it aside for later.', 'Use it to give a client a way to pause when something feels like too much.', array['Adults', 'Teens']::text[], '20 minutes', 'Guide the imagery in session with eyes open or closed as the client prefers. They design the container and practice closing it. This is a pause, not a way to avoid care, so plan with the client when they will return to support.', '[{"id": "f0", "type": "textarea", "label": "What my container looks like"}, {"id": "f1", "type": "textarea", "label": "How I close it"}, {"id": "f2", "type": "textarea", "label": "What helps me feel steady after"}, {"id": "f3", "type": "textarea", "label": "Who I can reach out to for support"}]'::jsonb, array['PTSD and trauma', 'containment', 'stabilization', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('grounding-scavenger-hunt-card-game', 'Grounding Scavenger Hunt Card Game', 'game'::resource_kind, 'Players draw cards that send them to find colors, textures and sounds in the room.', 'Use it to practice grounding skills with a group or individual in a playful way.', array['Groups', 'Adults', 'Teens']::text[], '20 minutes', 'Cards name things to find, such as something cold or something blue. Rules: take turns drawing, find it, say it aloud, and describe it in detail. Keep the room calm and let anyone pass. Debrief on which cards helped most.', '[{"id": "f0", "type": "textarea", "label": "The card I liked best"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I found it"}, {"id": "f2", "type": "textarea", "label": "How my body felt afterward"}, {"id": "f3", "type": "textarea", "label": "When I could use this outside session"}]'::jsonb, array['PTSD and trauma', 'grounding', 'group', 'coping skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('avoidance-ledger-of-costs-and-gains', 'Avoidance Ledger of Costs and Gains', 'worksheet'::resource_kind, 'The client lists what avoiding something gives them in the short run and what it costs over time.', 'Use it to help a client see the pull and the price of avoidance.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one avoided situation and fill in both columns honestly. Do not argue with the short-term gains, since relief is real. Then link the costs to what the client cares about and choose one small step to try.', '[{"id": "f0", "type": "textarea", "label": "Something I avoid"}, {"id": "f1", "type": "textarea", "label": "What avoiding it gives me"}, {"id": "f2", "type": "textarea", "label": "What avoiding it costs me"}, {"id": "f3", "type": "textarea", "label": "What I care about that it gets in the way of"}, {"id": "f4", "type": "textarea", "label": "One small step I could try"}]'::jsonb, array['anxiety', 'avoidance', 'values', 'exposure']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('uncertainty-experiment-log', 'Uncertainty Experiment Log', 'cbt'::resource_kind, 'The client tests what happens when they leave a what-if unanswered for a set time.', 'Use it to help a client practice living with not knowing.', array['Adults', 'Teens']::text[], 'One week', 'Choose a what-if the client keeps trying to settle and agree to leave it open for a set time. Predict beforehand what will happen, then log the actual result. Look for the gap between the prediction and the result.', '[{"id": "f0", "type": "textarea", "label": "The what-if I will leave open"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "What I did instead of trying to settle it"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}]'::jsonb, array['anxiety', 'uncertainty', 'behavioral experiments', 'worry']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('anxiety-forecast-watching-practice', 'Anxiety Forecast Watching Practice', 'act'::resource_kind, 'The client describes anxiety as weather passing over a landscape while they keep walking.', 'Use it to help a client carry anxiety along while moving toward what matters.', array['Adults', 'Teens']::text[], '20 minutes', 'Introduce the weather image and let the client adapt it. They name today''s weather, notice how it moves, and choose where they are walking. Check that it does not turn into a way of pushing the feeling away.', '[{"id": "f0", "type": "textarea", "label": "Today''s anxiety weather"}, {"id": "f1", "type": "textarea", "label": "How it changed when I watched it"}, {"id": "f2", "type": "textarea", "label": "Where I want to keep walking"}, {"id": "f3", "type": "textarea", "label": "One step I will take in any weather"}]'::jsonb, array['anxiety', 'mindfulness', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('self-validation-for-anxious-moments-card', 'Self-Validation for Anxious Moments Card', 'dbt'::resource_kind, 'The client writes short validating statements to say to themselves when anxiety is high.', 'Use it to help a client meet anxious moments with understanding instead of criticism.', array['Adults', 'Teens']::text[], '15 minutes', 'Explain that validating is not agreeing that danger is real but recognizing that the feeling makes sense. The client drafts phrases in their own voice and tries them aloud. Keep the card small enough to carry.', '[{"id": "f0", "type": "textarea", "label": "A time anxiety hit hard"}, {"id": "f1", "type": "textarea", "label": "What my body and mind were doing"}, {"id": "f2", "type": "textarea", "label": "A validating thing I could say to myself"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['anxiety', 'validation', 'emotion regulation', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('anxiety-superhero-shield-craft', 'Anxiety Superhero Shield Craft', 'kids'::resource_kind, 'The child decorates a paper shield with the helpers and skills that protect them when worry shows up.', 'Use it to help a child remember the helpers and skills they can call on.', array['Children']::text[], '30 minutes', 'Cut a shield shape and let the child draw their helpers, calming moves and brave words on it. Role-play a worry moment holding the shield. Parents learn the words on the shield and cue them gently at home.', '[{"id": "f0", "type": "textarea", "label": "A helper who is on my shield"}, {"id": "f1", "type": "textarea", "label": "A calming move I drew"}, {"id": "f2", "type": "textarea", "label": "Brave words I put on it"}, {"id": "f3", "type": "textarea", "label": "Where my shield will live at home"}]'::jsonb, array['anxiety', 'courage', 'craft', 'coping skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('low-energy-day-small-doable-list', 'Low-Energy Day Small Doable List', 'worksheet'::resource_kind, 'The client builds a short list of tiny tasks to use on days when energy is low.', 'Use it to give a client a gentle fallback list for low-energy days.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write tasks that take five minutes or less and sort them by effort. The list is a floor, not a goal. Remind them that doing one item counts. Review in a week and swap out items that did not fit.', '[{"id": "f0", "type": "textarea", "label": "Tiny things I can do in five minutes"}, {"id": "f1", "type": "textarea", "label": "Tasks that take almost no energy"}, {"id": "f2", "type": "textarea", "label": "One thing that usually helps a little"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself when I do just one"}]'::jsonb, array['depression', 'behavioral activation', 'self-care', 'routines']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('negative-filter-lens-swap-page', 'Negative Filter Lens Swap Page', 'cbt'::resource_kind, 'The client lists what a negative filter left out of a recent day and what a wider lens includes.', 'Use it to help a client widen the lens on a day that seemed all bad.', array['Adults', 'Teens']::text[], '25 minutes', 'Take a day the client called terrible and ask for the filtered version first. Then ask what else happened, however small. The aim is not forced positivity but a fuller picture. Keep their experience of the bad parts validated.', '[{"id": "f0", "type": "textarea", "label": "How I described the day"}, {"id": "f1", "type": "textarea", "label": "What the filter left out"}, {"id": "f2", "type": "textarea", "label": "Small moments that were neutral or okay"}, {"id": "f3", "type": "textarea", "label": "A fuller way to describe the day"}]'::jsonb, array['depression', 'cognitive restructuring', 'thought records', 'mood']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('values-when-motivation-is-missing-page', 'Values When Motivation Is Missing Page', 'act'::resource_kind, 'The client picks a small action tied to a value while motivation is low and notes what happens.', 'Use it to help a client act on a value without waiting to feel like it.', array['Adults', 'Teens']::text[], '25 minutes', 'Explain that motivation often follows action. The client picks a value and the smallest version of an action that fits it. Plan when and where, and track mood before and after without expecting a change every time.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "The smallest action that fits it"}, {"id": "f2", "type": "textarea", "label": "When and where I will do it"}, {"id": "f3", "type": "textarea", "label": "How I felt before and after"}]'::jsonb, array['depression', 'values', 'committed action', 'behavioral activation']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('short-term-positives-daily-pick-card', 'Short-Term Positives Daily Pick Card', 'dbt'::resource_kind, 'The client picks one small pleasant thing each day from a menu and notes it.', 'Use it to help a client build in small pleasant moments day by day.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Create a menu of small pleasant things with the client, from a favorite song to a short walk. Each day they choose one and fully attend to it. Review which ones matter most and drop any that feel like chores.', '[{"id": "f0", "type": "textarea", "label": "My menu of small pleasant things"}, {"id": "f1", "type": "textarea", "label": "What I picked today"}, {"id": "f2", "type": "textarea", "label": "What I noticed while doing it"}, {"id": "f3", "type": "textarea", "label": "Which ones I want to keep"}]'::jsonb, array['depression', 'emotion regulation', 'pleasant events', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('tiny-step-dice-roll-game', 'Tiny Step Dice Roll Game', 'game'::resource_kind, 'Players roll a die to pick a tiny action from a list they made, and celebrate completing it.', 'Use it to make small steps feel lighter in a group or individual session.', array['Groups', 'Adults', 'Teens']::text[], '25 minutes', 'Each player lists six tiny actions, one per die face. Rules: roll, do or plan the action, and share with the group. Cheers for any attempt. Debrief on which steps felt easiest and what made starting hard.', '[{"id": "f0", "type": "textarea", "label": "My six tiny actions"}, {"id": "f1", "type": "textarea", "label": "The one I rolled"}, {"id": "f2", "type": "textarea", "label": "When I will do it"}, {"id": "f3", "type": "textarea", "label": "How it felt to cheer for small steps"}]'::jsonb, array['depression', 'behavioral activation', 'group', 'motivation']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('body-doubling-session-planner', 'Body Doubling Session Planner', 'worksheet'::resource_kind, 'The client plans a working session alongside another person and sets simple goals for it.', 'Use it to help a client use company to get started on tasks.', array['Adults', 'Teens']::text[], '20 minutes', 'Explore who could sit with the client, in person or online, and what task they would do. Keep the goal small and set a timer. Review how having someone nearby changed starting and staying with the task.', '[{"id": "f0", "type": "textarea", "label": "A task I want to do"}, {"id": "f1", "type": "textarea", "label": "Who could be with me"}, {"id": "f2", "type": "textarea", "label": "What I will do in the first ten minutes"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['ADHD', 'executive skills', 'routines', 'planning']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('task-chunking-and-time-boxing-log', 'Task Chunking and Time Boxing Log', 'cbt'::resource_kind, 'The client breaks a task into steps, gives each a time box and logs what actually happened.', 'Use it to help a client turn a big task into steps they can start.', array['Adults', 'Teens']::text[], 'One week', 'Pick one stuck task and have the client list the very first step. Assign short time boxes and track guess versus actual. Notice thoughts that show up at the start and keep the log neutral, not a performance review.', '[{"id": "f0", "type": "textarea", "label": "The task I am chunking"}, {"id": "f1", "type": "textarea", "label": "The first tiny step"}, {"id": "f2", "type": "textarea", "label": "Time I guessed and time it took"}, {"id": "f3", "type": "textarea", "label": "Thoughts that came up when starting"}]'::jsonb, array['ADHD', 'time management', 'executive skills', 'self-monitoring']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('wandering-attention-return-practice', 'Wandering Attention Return Practice', 'act'::resource_kind, 'The client practices noticing that attention has drifted and gently returning without self-criticism.', 'Use it to help a client treat drifting attention with kindness.', array['Adults', 'Teens']::text[], 'Ten minutes daily for a week', 'Pick a short, concrete anchor such as a sound or a task step. The client notices each drift and returns, and logs how many times they came back as a win. Watch for clients who judge drifting as failure.', '[{"id": "f0", "type": "textarea", "label": "What I used as an anchor"}, {"id": "f1", "type": "textarea", "label": "When I noticed my attention had wandered"}, {"id": "f2", "type": "textarea", "label": "What I said to myself when I returned"}, {"id": "f3", "type": "textarea", "label": "What I want to try next"}]'::jsonb, array['ADHD', 'mindfulness', 'attention', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('impulse-pause-checklist', 'Impulse Pause Checklist', 'dbt'::resource_kind, 'The client keeps a short checklist to run before acting on a strong impulse.', 'Use it to give a client a quick pause between an urge and an action.', array['Adults', 'Teens']::text[], '20 minutes', 'Build a three to five step checklist the client can glance at, such as breathe, name the urge, ask what I want, then decide. Practice in session with a small impulse. Keep the list on the phone or in a pocket.', '[{"id": "f0", "type": "textarea", "label": "An impulse I want to slow down"}, {"id": "f1", "type": "textarea", "label": "Steps on my checklist"}, {"id": "f2", "type": "textarea", "label": "Where I will keep it"}, {"id": "f3", "type": "textarea", "label": "A time I tried it and what happened"}]'::jsonb, array['ADHD', 'impulse control', 'emotion regulation', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('distraction-dodge-focus-game', 'Distraction Dodge Focus Game', 'game'::resource_kind, 'Players try a focus task while the group adds friendly distractions, then compare strategies.', 'Use it to let players test focus strategies in a safe, playful setting.', array['Groups', 'Teens', 'Children']::text[], '25 minutes', 'Rules: a player works on a simple task for two minutes while others make gentle noises or movements. Rotate turns. Debrief on strategies that helped, such as noise-blocking or breaking the task, and what each player will try.', '[{"id": "f0", "type": "textarea", "label": "What distracted me most"}, {"id": "f1", "type": "textarea", "label": "A strategy I used"}, {"id": "f2", "type": "textarea", "label": "A strategy I heard from someone else"}, {"id": "f3", "type": "textarea", "label": "What I will try on a real task"}]'::jsonb, array['ADHD', 'attention', 'group', 'skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('trigger-urge-choice-map', 'Trigger, Urge, Choice Map', 'worksheet'::resource_kind, 'The client maps a recent trigger, the urge that followed and the choices open at each point.', 'Use it to help a client see the places where a different choice is possible.', array['Adults']::text[], '30 minutes', 'Walk through a recent urge from the trigger onward and mark each point where another choice was possible. Keep language about substance use and urges, not labels. Add a plan for one of those points.', '[{"id": "f0", "type": "textarea", "label": "The trigger"}, {"id": "f1", "type": "textarea", "label": "The urge and where I felt it"}, {"id": "f2", "type": "textarea", "label": "The choice I made"}, {"id": "f3", "type": "textarea", "label": "A different choice that was possible"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['addiction', 'urges', 'triggers', 'relapse prevention']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('permission-giving-thoughts-check-page', 'Permission-Giving Thoughts Check Page', 'cbt'::resource_kind, 'The client spots thoughts that give permission to use a substance and writes a response.', 'Use it to help a client catch the thoughts that open the door to substance use.', array['Adults']::text[], '25 minutes', 'Give examples such as one time will not matter. The client lists their own and writes a response that comes from what they value. Role-play the thought and the response aloud so it is ready when needed.', '[{"id": "f0", "type": "textarea", "label": "A thought that gives me permission"}, {"id": "f1", "type": "textarea", "label": "When it usually shows up"}, {"id": "f2", "type": "textarea", "label": "What I value that it works against"}, {"id": "f3", "type": "textarea", "label": "My response in my own words"}]'::jsonb, array['addiction', 'relapse prevention', 'thought records', 'triggers']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-urges-without-acting-page', 'Willing to Feel Urges Without Acting Page', 'act'::resource_kind, 'The client practices noticing an urge as a sensation and choosing an action that fits their values.', 'Use it to help a client carry an urge without acting on it.', array['Adults']::text[], '25 minutes', 'Guide the client to find where the urge sits in the body and describe it in plain words. Then name a value and choose an action. Check in on how long the urge lasted. Treat any difficulty as useful information.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body"}, {"id": "f1", "type": "textarea", "label": "What the urge says"}, {"id": "f2", "type": "textarea", "label": "A value I care about"}, {"id": "f3", "type": "textarea", "label": "What I did instead of acting on the urge"}]'::jsonb, array['addiction', 'urges', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('distract-and-self-soothe-menu-for-urges', 'Distract and Self-Soothe Menu for Urges', 'dbt'::resource_kind, 'The client builds a menu of ways to distract and soothe through an urge using the senses.', 'Use it to give a client a ready list when an urge shows up.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to list activities by sense and by effort, including options for different places. Practice two in session. Keep the menu where they can reach it quickly, and revisit the list after real use.', '[{"id": "f0", "type": "textarea", "label": "Things I can do with my hands"}, {"id": "f1", "type": "textarea", "label": "Things I can listen to or watch"}, {"id": "f2", "type": "textarea", "label": "Soothing things for taste, smell or touch"}, {"id": "f3", "type": "textarea", "label": "People I can contact"}]'::jsonb, array['addiction', 'urges', 'distress tolerance', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('saying-no-practice-scene-cards', 'Saying No Practice Scene Cards', 'game'::resource_kind, 'Players draw offers or pressure situations and practice saying no in different ways.', 'Use it to help players practice clear refusals around substance use.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Write offer scenes on cards. Rules: draw a card, respond in role, and the group gives one thing that worked. Rotate roles. Debrief on which refusals felt natural and what each player will say in real life.', '[{"id": "f0", "type": "textarea", "label": "A situation I drew"}, {"id": "f1", "type": "textarea", "label": "My refusal in my own words"}, {"id": "f2", "type": "textarea", "label": "A refusal I heard that I liked"}, {"id": "f3", "type": "textarea", "label": "Who can support me in a real situation"}]'::jsonb, array['addiction', 'refusal skills', 'group', 'relapse prevention']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('anger-cool-down-menu-by-intensity', 'Anger Cool-Down Menu by Intensity', 'worksheet'::resource_kind, 'The client matches skills to anger levels from simmering to boiling.', 'Use it to help a client pick the right skill for how hot anger has become.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw a scale with the client and describe how each level looks and feels. Fill in skills that suit each level, noting that big skills fit the high end. Practice one from each level and revisit in a week.', '[{"id": "f0", "type": "textarea", "label": "What simmering feels like for me"}, {"id": "f1", "type": "textarea", "label": "Skills I use when it is low"}, {"id": "f2", "type": "textarea", "label": "Skills I use when it is high"}, {"id": "f3", "type": "textarea", "label": "What I do when I cannot use a skill right away"}]'::jsonb, array['anger management', 'anger', 'coping skills', 'emotion regulation']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('demands-into-preferences-rewrite-page', 'Demands Into Preferences Rewrite Page', 'cbt'::resource_kind, 'The client rewrites rigid musts and shoulds about others into flexible preferences.', 'Use it to help a client soften the demands that fuel anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect a few musts and shoulds that came up in a recent angry moment. Rewrite each as I would prefer without dismissing the feeling. Notice how the body responds to the new wording and keep the phrases the client believes.', '[{"id": "f0", "type": "textarea", "label": "A should or must I had"}, {"id": "f1", "type": "textarea", "label": "What I prefer instead"}, {"id": "f2", "type": "textarea", "label": "How my body felt with each wording"}, {"id": "f3", "type": "textarea", "label": "What I will say next time"}]'::jsonb, array['anger management', 'anger', 'cognitive restructuring', 'flexibility']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('unhooking-from-the-urge-to-strike-back', 'Unhooking From the Urge to Strike Back', 'act'::resource_kind, 'The client notices the pull to retaliate and chooses a values-based action instead.', 'Use it to help a client choose a response that fits who they want to be.', array['Adults', 'Teens']::text[], '25 minutes', 'Describe the urge as a pull that can be noticed. The client names it, notes the body, and asks what they want the moment to be about. Practice a values-based reply aloud and discuss real-life obstacles.', '[{"id": "f0", "type": "textarea", "label": "What I felt pulled to do"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f2", "type": "textarea", "label": "What I want this moment to be about"}, {"id": "f3", "type": "textarea", "label": "A response I can live with"}]'::jsonb, array['anger management', 'anger', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('stop-skill-practice-page', 'STOP Skill Practice Page', 'dbt'::resource_kind, 'The client rehearses stop, take a step back, observe and proceed mindfully before acting.', 'Use it to help a client pause before an angry action.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through the four steps and role-play with a mild trigger. The client writes what each step looks like for them. Link to a cue such as a hand squeeze or a phrase, and practice until it feels automatic.', '[{"id": "f0", "type": "textarea", "label": "A time I almost reacted"}, {"id": "f1", "type": "textarea", "label": "What stopping looks like for me"}, {"id": "f2", "type": "textarea", "label": "What I observe when I step back"}, {"id": "f3", "type": "textarea", "label": "How I will proceed mindfully"}]'::jsonb, array['anger management', 'anger', 'distress tolerance', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('volcano-pressure-release-craft', 'Volcano Pressure Release Craft', 'kids'::resource_kind, 'The child builds a volcano and fills it with the things that build pressure and the ways to let it out safely.', 'Use it to help a child learn that anger builds and can be released safely.', array['Children']::text[], '35 minutes', 'Build a volcano from paper or clay and add pressure words inside. Then pick safe release steps, such as squeezing a pillow or breathing. Parents learn the steps and offer them early when they see rising pressure.', '[{"id": "f0", "type": "textarea", "label": "Things that build pressure in me"}, {"id": "f1", "type": "textarea", "label": "How my body feels when pressure rises"}, {"id": "f2", "type": "textarea", "label": "Safe ways I can let it out"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can say to help"}]'::jsonb, array['anger management', 'anger', 'craft', 'parent coaching']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('doubt-versus-certainty-weekly-log', 'Doubt Versus Certainty Weekly Log', 'worksheet'::resource_kind, 'The client logs moments of doubt, the urge for certainty and what they did with it.', 'Use it to help a client see how the hunt for certainty shows up across a week.', array['Adults', 'Teens']::text[], 'One week', 'Have the client jot down doubts and what they did to feel sure, without trying to stop anything yet. Look together for patterns in time, place and cost. The log guides where to start a gradual plan, at the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "The doubt that showed up"}, {"id": "f1", "type": "textarea", "label": "What I did to feel sure"}, {"id": "f2", "type": "textarea", "label": "How long it took"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['OCD', 'uncertainty', 'self-monitoring', 'rituals']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-normalizing-page', 'Intrusive Thought Normalizing Page', 'cbt'::resource_kind, 'The client learns that unwanted thoughts are common and practices not treating them as messages.', 'Use it to help a client see that having a thought is not the same as meaning it.', array['Adults', 'Teens']::text[], '25 minutes', 'Explain that many people have odd or upsetting thoughts and that the meaning given to them is what makes them stick. The client lists such thoughts and what they have taken them to mean. Move gently and avoid reassurance.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought I have had"}, {"id": "f1", "type": "textarea", "label": "What I took it to mean about me"}, {"id": "f2", "type": "textarea", "label": "What happens when I treat it as important"}, {"id": "f3", "type": "textarea", "label": "What it might look like to let it pass"}]'::jsonb, array['OCD', 'intrusive thoughts', 'cognitive restructuring', 'OCD-related']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('uninvited-guest-metaphor-page', 'Uninvited Guest Metaphor Page', 'act'::resource_kind, 'The client pictures a thought as an uninvited guest and practices choosing how to host without following orders.', 'Use it to help a client carry thoughts without obeying them.', array['Adults', 'Teens']::text[], '20 minutes', 'Tell the guest metaphor and let the client adapt it. They name the guest''s demands and decide what to do with the evening anyway. Check that the image does not turn into a new way of arguing with the thought.', '[{"id": "f0", "type": "textarea", "label": "The guest''s name and what it demands"}, {"id": "f1", "type": "textarea", "label": "What I usually do to please it"}, {"id": "f2", "type": "textarea", "label": "What I would do if I let it stay and kept going"}, {"id": "f3", "type": "textarea", "label": "A value I want to act on tonight"}]'::jsonb, array['OCD', 'defusion', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('mindful-noticing-of-urges-to-check', 'Mindful Noticing of Urges to Check', 'dbt'::resource_kind, 'The client observes the urge to check or redo without acting on it for a set time.', 'Use it to help a client watch an urge rise and fall.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a small, manageable urge and agree on a short wait in session. The client describes the urge, its intensity and how it changed over the minutes. Build up gradually and keep the client in charge of each step.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed"}, {"id": "f1", "type": "textarea", "label": "Intensity at the start"}, {"id": "f2", "type": "textarea", "label": "What I did while waiting"}, {"id": "f3", "type": "textarea", "label": "Intensity at the end and what I learned"}]'::jsonb, array['OCD', 'urges', 'mindfulness', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('uncertainty-dare-cards', 'Uncertainty Dare Cards', 'game'::resource_kind, 'Players draw small, safe dares to tolerate not knowing, such as leaving a text unchecked for a few minutes.', 'Use it to make practice with uncertainty lighter for a group.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Prepare dare cards that are mild and agreed in advance. Rules: draw, rate how hard it feels, do it or plan it, and rate again. Pass is always allowed. Debrief on what players noticed when they stayed with not knowing.', '[{"id": "f0", "type": "textarea", "label": "The dare I drew"}, {"id": "f1", "type": "textarea", "label": "How hard it felt before"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "What I would try next"}]'::jsonb, array['OCD', 'uncertainty', 'group', 'exposure']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('panic-rise-and-fall-sketch-page', 'Panic Rise and Fall Sketch Page', 'worksheet'::resource_kind, 'The client sketches how a panic wave rises, peaks and falls, and what they did at each point.', 'Use it to help a client see that panic comes in waves that pass.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client draw a recent wave and label the sensations, thoughts and actions along it. Notice what pushed it up and what let it settle. Rule out medical concerns through the usual channels if needed.', '[{"id": "f0", "type": "textarea", "label": "Where the wave started"}, {"id": "f1", "type": "textarea", "label": "Sensations at the peak"}, {"id": "f2", "type": "textarea", "label": "What I did and thought"}, {"id": "f3", "type": "textarea", "label": "How it passed"}]'::jsonb, array['panic attacks', 'panic', 'self-monitoring', 'awareness']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('sensation-interpretation-check-page', 'Sensation Interpretation Check Page', 'cbt'::resource_kind, 'The client matches each body sensation to a scary interpretation and a more likely explanation.', 'Use it to help a client test frightening readings of normal sensations.', array['Adults', 'Teens']::text[], '25 minutes', 'List common sensations such as a racing heart or dizziness and the interpretation the client reaches for. Brainstorm more likely explanations with them. Follow with practice in session that brings on a mild sensation.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice"}, {"id": "f1", "type": "textarea", "label": "What I fear it means"}, {"id": "f2", "type": "textarea", "label": "Other likely explanations"}, {"id": "f3", "type": "textarea", "label": "What happened when I tested it"}]'::jsonb, array['panic attacks', 'panic', 'cognitive restructuring', 'interoceptive practice']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('carrying-panic-along-page', 'Carrying Panic Along Page', 'act'::resource_kind, 'The client practices doing a valued activity with sensations present instead of waiting for them to go.', 'Use it to help a client pursue what matters with panic sensations along for the ride.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an activity the client avoids and plan a short version. They name the sensations they expect and what they will tell themselves. Rate willingness before and after. Stay flexible about how long they do it.', '[{"id": "f0", "type": "textarea", "label": "An activity I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "Sensations I expect to bring along"}, {"id": "f2", "type": "textarea", "label": "What I will say to myself"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['panic attacks', 'panic', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('accepting-a-surge-radical-acceptance-card', 'Accepting a Surge Radical Acceptance Card', 'dbt'::resource_kind, 'The client writes accepting statements to use as a panic surge begins and practices turning the mind toward acceptance.', 'Use it to help a client stop fighting a surge that is already here.', array['Adults', 'Teens']::text[], '20 minutes', 'Explain that fighting panic can add fuel. The client writes short statements such as this is a wave and I can ride it. Practice with breath and a half smile in session and add the card to a phone note.', '[{"id": "f0", "type": "textarea", "label": "A surge I fought recently"}, {"id": "f1", "type": "textarea", "label": "What fighting it looked like"}, {"id": "f2", "type": "textarea", "label": "Accepting words I will use"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card"}]'::jsonb, array['panic attacks', 'panic', 'radical acceptance', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('calm-breath-pinwheel-craft', 'Calm Breath Pinwheel Craft', 'kids'::resource_kind, 'The child makes a pinwheel and uses it to practice slow breaths.', 'Use it to give a child a fun way to practice slow breathing before big feelings.', array['Children', 'Teens']::text[], '25 minutes', 'Make a pinwheel together, then practice slow breaths that make it spin gently. Try a fast breath too to feel the difference. Parents keep the pinwheel handy and join in with their own breaths at calm moments.', '[{"id": "f0", "type": "textarea", "label": "What my pinwheel looks like"}, {"id": "f1", "type": "textarea", "label": "What my body felt like with slow breath"}, {"id": "f2", "type": "textarea", "label": "What I felt like with fast breath"}, {"id": "f3", "type": "textarea", "label": "Where we keep the pinwheel at home"}]'::jsonb, array['panic attacks', 'panic', 'breathing', 'craft']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('parent-trigger-pause-plan', 'Parent Trigger Pause Plan', 'worksheet'::resource_kind, 'The parent maps what sets them off and a pause they can take before responding.', 'Use it to help a parent plan a pause for the moments they react fastest.', array['Adults']::text[], '25 minutes', 'Ask the parent to list moments when they react quickly and what the pause could look like. Keep the plan realistic, such as three breaths or leaving the room for a minute. Rehearse it aloud and revisit after a week.', '[{"id": "f0", "type": "textarea", "label": "Moments that trigger me most"}, {"id": "f1", "type": "textarea", "label": "What I usually do"}, {"id": "f2", "type": "textarea", "label": "The pause I will try"}, {"id": "f3", "type": "textarea", "label": "What I will say to my child afterward"}]'::jsonb, array['parenting', 'parent coaching', 'emotion regulation', 'boundaries']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('expectations-versus-child-stage-check', 'Expectations Versus Child Stage Check', 'cbt'::resource_kind, 'The parent compares what they expect with what a child of that age can usually do.', 'Use it to help a parent adjust expectations to a child''s stage.', array['Adults']::text[], '25 minutes', 'The parent writes what they expect in a situation and what the child did. Talk through typical skills at that age and note where expectations may be set too high or too low. Avoid blame for either side.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What I expected"}, {"id": "f2", "type": "textarea", "label": "What my child did"}, {"id": "f3", "type": "textarea", "label": "An expectation I could adjust"}]'::jsonb, array['parenting', 'parent coaching', 'expectations', 'cognitive restructuring']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('present-at-bedtime-practice', 'Present at Bedtime Practice', 'act'::resource_kind, 'The parent practices full attention for a short bedtime routine and notes what they noticed.', 'Use it to help a parent be fully present for a small daily moment.', array['Adults']::text[], 'Ten minutes daily for a week', 'Pick a short daily routine and ask for phone-free attention. The parent notices the child''s face, voice and mood, and their own thoughts. Review what stood out. Skip guilt about days it did not happen.', '[{"id": "f0", "type": "textarea", "label": "The routine I chose"}, {"id": "f1", "type": "textarea", "label": "What I noticed about my child"}, {"id": "f2", "type": "textarea", "label": "What my mind kept pulling me toward"}, {"id": "f3", "type": "textarea", "label": "What I value about this time"}]'::jsonb, array['parenting', 'mindfulness', 'values', 'parent coaching']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('weekly-parenting-team-huddle', 'Weekly Parenting Team Huddle', 'couples'::resource_kind, 'Parents hold a short weekly huddle to share wins, align on one issue and plan the week.', 'Use it to help co-parents stay on the same team.', array['Couples']::text[], '20 minutes weekly', 'Parent A and Parent B each bring one win and one concern. They choose one issue to align on and plan who does what. Keep it short, timed and free of blame. Review how it is going after a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Parent A: a win this week"}, {"id": "f1", "type": "textarea", "label": "Parent B: a win this week"}, {"id": "f2", "type": "textarea", "label": "The one issue we will align on"}, {"id": "f3", "type": "textarea", "label": "Who does what this week"}]'::jsonb, array['parenting', 'co-parenting', 'communication', 'planning']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('family-praise-jar-project', 'Family Praise Jar Project', 'kids'::resource_kind, 'The family decorates a jar and adds notes about things each person did well.', 'Use it to help a family notice and name good moments.', array['Children', 'Adults']::text[], '30 minutes', 'Decorate the jar together and agree that notes are specific and kind. Parents add notes too, and everyone reads a few at a set time each week. Be sure praise is about effort and actions, not only results.', '[{"id": "f0", "type": "textarea", "label": "Something I did well this week"}, {"id": "f1", "type": "textarea", "label": "Something someone else did well"}, {"id": "f2", "type": "textarea", "label": "When we will read the jar"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear it"}]'::jsonb, array['parenting', 'parent coaching', 'praise', 'craft']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('daily-rhythm-sketch-for-new-parents', 'Daily Rhythm Sketch for New Parents', 'worksheet'::resource_kind, 'The parent sketches a loose daily rhythm around feeds and sleep, with room for rest.', 'Use it to help a new parent shape days with gentleness and flexibility.', array['Adults']::text[], '25 minutes', 'Draw the day as blocks rather than a timetable. The parent marks fixed points and places rest, food and contact with others. Treat it as a draft and adjust it weekly. Ask what support would make the rhythm easier.', '[{"id": "f0", "type": "textarea", "label": "Fixed points in my day"}, {"id": "f1", "type": "textarea", "label": "Where rest can fit"}, {"id": "f2", "type": "textarea", "label": "Where I can connect with someone"}, {"id": "f3", "type": "textarea", "label": "What I will let go of for now"}]'::jsonb, array['perinatal and postpartum', 'new parents', 'routines', 'self-care']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('comparison-thought-check-for-new-parents', 'Comparison Thought Check for New Parents', 'cbt'::resource_kind, 'The parent catches comparison thoughts about other parents and writes kinder, fairer replies.', 'Use it to help a new parent ease the pull of comparing.', array['Adults']::text[], '20 minutes', 'Collect thoughts such as everyone else manages better. The parent notes where the comparison came from, often social media, and what is left out of it. Write a reply that is fair to their own situation.', '[{"id": "f0", "type": "textarea", "label": "A comparison thought"}, {"id": "f1", "type": "textarea", "label": "Where it came from"}, {"id": "f2", "type": "textarea", "label": "What the comparison leaves out"}, {"id": "f3", "type": "textarea", "label": "A fairer reply"}]'::jsonb, array['perinatal and postpartum', 'new parents', 'cognitive restructuring', 'self-compassion']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('values-in-the-newborn-season-page', 'Values in the Newborn Season Page', 'act'::resource_kind, 'The parent names what matters most in this season and picks one small way to act on it each day.', 'Use it to help a parent stay linked to values while life is upended.', array['Adults']::text[], '25 minutes', 'Acknowledge how much has changed. Help the parent choose values that fit this season, such as presence or care for themselves. Pick very small daily actions. Check in about support, and about mood if it seems heavy.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me right now"}, {"id": "f1", "type": "textarea", "label": "A small way to act on it"}, {"id": "f2", "type": "textarea", "label": "What gets in the way"}, {"id": "f3", "type": "textarea", "label": "Support I could ask for"}]'::jsonb, array['perinatal and postpartum', 'values', 'new parents', 'self-compassion']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-isolation-plan', 'Opposite Action for Isolation Plan', 'dbt'::resource_kind, 'The parent plans a small step toward people on days the pull is to stay shut in.', 'Use it to help a new parent reach out when the urge is to withdraw.', array['Adults']::text[], '20 minutes', 'Name the urge to withdraw and the reasons for it, then choose one small contact, such as a text or a short walk with the baby. Keep steps small and baby-friendly. Review what the step brought up.', '[{"id": "f0", "type": "textarea", "label": "The urge I notice on hard days"}, {"id": "f1", "type": "textarea", "label": "A small step toward people"}, {"id": "f2", "type": "textarea", "label": "Who I will reach out to"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['perinatal and postpartum', 'isolation', 'opposite action', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('rest-and-night-shift-planner-for-two', 'Rest and Night Shift Planner for Two', 'couples'::resource_kind, 'Partners agree on night duties, protected rest and how to check in about how each is doing.', 'Use it to help partners share night work and protect rest.', array['Couples']::text[], '30 minutes', 'Partner A and Partner B list what nights require and who can do each task, including protected sleep blocks. Add a brief daily check-in about how each is feeling. Revisit as the baby''s needs change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I can take on at night"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can take on at night"}, {"id": "f2", "type": "textarea", "label": "Protected rest blocks"}, {"id": "f3", "type": "textarea", "label": "How we will check in each day"}]'::jsonb, array['perinatal and postpartum', 'new parents', 'rest', 'communication']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('compliment-receiving-practice-sheet', 'Compliment Receiving Practice Sheet', 'worksheet'::resource_kind, 'The client practices accepting compliments with a simple thank-you and notes what comes up.', 'Use it to help a client take in kind words instead of deflecting them.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to track compliments they received and how they reacted. Practice a simple thank-you aloud. Notice thoughts that argue with the compliment and write a gentler reply for the next one.', '[{"id": "f0", "type": "textarea", "label": "A compliment I received"}, {"id": "f1", "type": "textarea", "label": "How I responded"}, {"id": "f2", "type": "textarea", "label": "The thought that argued with it"}, {"id": "f3", "type": "textarea", "label": "What I will say next time"}]'::jsonb, array['self-esteem', 'strengths', 'communication']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('critic-to-coach-voice-rewrite', 'Critic to Coach Voice Rewrite', 'cbt'::resource_kind, 'The client rewrites a harsh self-critical line in the voice of a fair, encouraging coach.', 'Use it to help a client shift from harsh criticism to useful coaching.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect a recent self-critical line and ask what a good coach would say instead, with the same honesty but more warmth. Practice aloud. Notice whether the coaching voice feels believable and adjust the wording.', '[{"id": "f0", "type": "textarea", "label": "The critical line"}, {"id": "f1", "type": "textarea", "label": "What a fair coach would say"}, {"id": "f2", "type": "textarea", "label": "What I need to hear"}, {"id": "f3", "type": "textarea", "label": "How I will use the coach voice this week"}]'::jsonb, array['self-esteem', 'self-compassion', 'cognitive restructuring']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('worth-is-not-a-report-card-page', 'Worth Is Not a Report Card Page', 'act'::resource_kind, 'The client explores how often they grade their worth by outcomes and what they would choose instead.', 'Use it to help a client loosen the link between worth and performance.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list areas where they score themselves. Wonder together what would change if worth was a given rather than a grade. Link to values and one action to try this week.', '[{"id": "f0", "type": "textarea", "label": "Areas where I grade myself"}, {"id": "f1", "type": "textarea", "label": "The grade I usually give"}, {"id": "f2", "type": "textarea", "label": "What I would do if my worth were not up for grading"}, {"id": "f3", "type": "textarea", "label": "A value I will act on this week"}]'::jsonb, array['self-esteem', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('validating-myself-first-practice', 'Validating Myself First Practice', 'dbt'::resource_kind, 'The client practices naming their own feelings and experiences as understandable before looking to others to do so.', 'Use it to help a client offer themselves validation.', array['Adults', 'Teens']::text[], '20 minutes', 'Explain levels of validation briefly. The client describes a recent upset and writes a validating line to themselves. Practice in session and watch for sliding into self-criticism. Praise attempts.', '[{"id": "f0", "type": "textarea", "label": "A recent upset"}, {"id": "f1", "type": "textarea", "label": "What makes it understandable"}, {"id": "f2", "type": "textarea", "label": "A validating line I can say to myself"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['self-esteem', 'validation', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('strength-spotting-card-swap', 'Strength Spotting Card Swap', 'game'::resource_kind, 'Players write strengths on cards for each other and trade them, then talk about which feel true.', 'Use it to help a group notice strengths in themselves and others.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Each player writes one real strength for every other person. Rules: pass cards face-down, read your own, and share one that surprised you. Debrief on which ones felt true and how it feels to receive them.', '[{"id": "f0", "type": "textarea", "label": "A strength someone saw in me"}, {"id": "f1", "type": "textarea", "label": "One that surprised me"}, {"id": "f2", "type": "textarea", "label": "A strength I wrote and why"}, {"id": "f3", "type": "textarea", "label": "How I will remember these"}]'::jsonb, array['self-esteem', 'strengths', 'group']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('small-social-steps-ladder', 'Small Social Steps Ladder', 'worksheet'::resource_kind, 'The client builds a ladder of small social actions from easy to harder, with a plan for the first rung.', 'Use it to help a client approach social situations in small, chosen steps.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask for ten social actions and sort them by difficulty with the client. Choose a first rung that feels doable and plan when to try it. Rate fear before and after. Move up only when the client is ready.', '[{"id": "f0", "type": "textarea", "label": "Social things I avoid or dread"}, {"id": "f1", "type": "textarea", "label": "My ladder, from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "The first rung and when I will try it"}, {"id": "f3", "type": "textarea", "label": "Fear before and after"}]'::jsonb, array['social anxiety', 'exposure', 'avoidance', 'social skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('after-event-replay-reality-check', 'After-Event Replay Reality Check', 'cbt'::resource_kind, 'The client compares their mental replay of a social event with what likely happened.', 'Use it to help a client temper harsh replays after social events.', array['Adults', 'Teens']::text[], '25 minutes', 'After a recent event, ask the client what the replay shows and what they think others noticed. Look for mind reading and selective memory. Write a fairer summary of the event.', '[{"id": "f0", "type": "textarea", "label": "The event"}, {"id": "f1", "type": "textarea", "label": "What my replay shows"}, {"id": "f2", "type": "textarea", "label": "What others probably noticed"}, {"id": "f3", "type": "textarea", "label": "A fairer summary"}]'::jsonb, array['social anxiety', 'rumination', 'cognitive restructuring', 'social skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('making-room-for-awkward-moments-page', 'Making Room for Awkward Moments Page', 'act'::resource_kind, 'The client practices staying in a socially awkward moment and choosing connection over escape.', 'Use it to help a client let awkward moments be part of connecting.', array['Adults', 'Teens']::text[], '25 minutes', 'Normalize that awkward moments come with connecting. The client names a feared awkward moment and what they usually do to avoid it. Choose a small values-based move to try and plan how to carry the discomfort.', '[{"id": "f0", "type": "textarea", "label": "An awkward moment I fear"}, {"id": "f1", "type": "textarea", "label": "What I usually do to escape it"}, {"id": "f2", "type": "textarea", "label": "Why connecting matters to me"}, {"id": "f3", "type": "textarea", "label": "A small move I will try"}]'::jsonb, array['social anxiety', 'values', 'acceptance', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('asking-for-something-small-practice', 'Asking for Something Small Practice', 'dbt'::resource_kind, 'The client practices making a small request to build confidence in speaking up.', 'Use it to help a client practice small asks in real situations.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a small request, such as asking for directions or a different seat. Role-play with the client using clear, brief language. Plan a real attempt and review how it went, noting the steps that were easier than expected.', '[{"id": "f0", "type": "textarea", "label": "A small thing I could ask for"}, {"id": "f1", "type": "textarea", "label": "How I will say it"}, {"id": "f2", "type": "textarea", "label": "Who I will try it with"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'assertiveness', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('say-hello-challenge-cards', 'Say Hello Challenge Cards', 'game'::resource_kind, 'Players draw tiny greeting or conversation challenges and report back on how each went.', 'Use it to make practicing small social moments feel lighter.', array['Groups', 'Teens']::text[], '25 minutes', 'Prepare cards with mild challenges such as greeting someone or sharing a favorite song. Rules: draw, choose to do now or later, then report. Pass is always fine. Debrief on what players noticed about their fear before and after.', '[{"id": "f0", "type": "textarea", "label": "The challenge I drew"}, {"id": "f1", "type": "textarea", "label": "What I predicted"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'social skills', 'group', 'exposure']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('good-days-and-hard-days-grief-calendar', 'Good Days and Hard Days Grief Calendar', 'worksheet'::resource_kind, 'The client marks days on a calendar and notes what made each easier or harder.', 'Use it to help a client see the ebb and flow of grief and what helps.', array['Adults', 'Teens']::text[], 'One month', 'Give the client a simple calendar and ask them to mark each day lightly, with a word or color. Look together for patterns, such as particular times or people. Avoid framing grief as steps to complete.', '[{"id": "f0", "type": "textarea", "label": "Days that felt hard and what made them so"}, {"id": "f1", "type": "textarea", "label": "Days that felt a bit lighter"}, {"id": "f2", "type": "textarea", "label": "What helped on hard days"}, {"id": "f3", "type": "textarea", "label": "What I want to remember about this month"}]'::jsonb, array['grief and loss', 'grief', 'self-monitoring', 'self-care']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('questions-without-answers-after-loss-page', 'Questions Without Answers After Loss Page', 'cbt'::resource_kind, 'The client lists unanswerable questions after a loss and practices holding them without needing an answer.', 'Use it to help a client carry the questions that have no answers.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to write the questions they keep asking, such as why or what if. Notice how the mind searches for a reason. Practice a kind line to say to oneself when the questions return.', '[{"id": "f0", "type": "textarea", "label": "Questions I keep asking"}, {"id": "f1", "type": "textarea", "label": "What happens when I search for an answer"}, {"id": "f2", "type": "textarea", "label": "A kind thing I can say to myself"}, {"id": "f3", "type": "textarea", "label": "Someone I can share the questions with"}]'::jsonb, array['grief and loss', 'grief', 'rumination', 'self-compassion']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('making-room-for-missing-them-practice', 'Making Room for Missing Them Practice', 'act'::resource_kind, 'The client allows missing someone to be present while choosing a small way to honor the relationship.', 'Use it to help a client carry love and loss together.', array['Adults', 'Teens']::text[], '25 minutes', 'Let the client describe what missing feels like in the body. Then pick a small act that honors the relationship. Go at their pace and expect tears. Offer silence when needed.', '[{"id": "f0", "type": "textarea", "label": "What missing them feels like"}, {"id": "f1", "type": "textarea", "label": "Something I loved about them"}, {"id": "f2", "type": "textarea", "label": "A small way to honor them this week"}, {"id": "f3", "type": "textarea", "label": "Who can be with me"}]'::jsonb, array['grief and loss', 'grief', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('grieving-differently-together-talk-guide', 'Grieving Differently Together Talk Guide', 'couples'::resource_kind, 'Partners share how each grieves and agree on how to support one another.', 'Use it to help partners respect different ways of grieving.', array['Couples']::text[], '40 minutes', 'Partner A and Partner B describe how they grieve and what support they want, without asking the other to grieve the same way. Agree on signals for needing space or company and plan a check-in.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What helps me from my partner"}, {"id": "f3", "type": "textarea", "label": "A signal we will use"}]'::jsonb, array['grief and loss', 'grief', 'communication', 'support']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('memory-rock-garden-craft', 'Memory Rock Garden Craft', 'kids'::resource_kind, 'The child paints rocks with memories of someone they miss and arranges them in a small garden.', 'Use it to give a child a hands-on way to remember someone.', array['Children']::text[], '35 minutes', 'Provide smooth rocks and paint and let the child decide what to put on each one. Arrange them in a small garden at home. Parents are invited to share their own memories. Follow the child''s lead and keep the mood open.', '[{"id": "f0", "type": "textarea", "label": "Who I am remembering"}, {"id": "f1", "type": "textarea", "label": "What I painted on the rocks"}, {"id": "f2", "type": "textarea", "label": "A favorite memory"}, {"id": "f3", "type": "textarea", "label": "Where we will keep the garden"}]'::jsonb, array['grief and loss', 'grief', 'craft', 'memories']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('needs-and-wants-sort-for-two', 'Needs and Wants Sort for Two', 'couples'::resource_kind, 'Each partner sorts what they need from the relationship from what they would like, then they compare.', 'Use it to help partners tell core needs from preferences before a hard talk.', array['Couples']::text[], '35 minutes', 'Partner A and Partner B each sort items into needs, wants and flexible, then share one need they have not said plainly. The listening partner reflects before responding. Keep it to one need each and plan a next step together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my needs and my wants"}, {"id": "f1", "type": "textarea", "label": "Partner A: a need I have not said aloud"}, {"id": "f2", "type": "textarea", "label": "Partner B: my needs and my wants"}, {"id": "f3", "type": "textarea", "label": "Partner B: a need I have not said aloud"}, {"id": "f4", "type": "textarea", "label": "One thing we will each try"}]'::jsonb, array['relationship issues', 'communication', 'needs', 'boundaries']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('interpretation-check-in-conflict-page', 'Interpretation Check in Conflict Page', 'cbt'::resource_kind, 'The client lists the story they told in a conflict and other stories that could also fit.', 'Use it to help a client slow down the stories that heat up conflict.', array['Adults', 'Teens']::text[], '25 minutes', 'Take a recent conflict and write the facts, the interpretation and the feeling. Brainstorm other possible reasons for the other person''s behavior. Ask what the client could check out rather than assume.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The story I told myself"}, {"id": "f2", "type": "textarea", "label": "Other stories that could fit"}, {"id": "f3", "type": "textarea", "label": "What I could ask to check"}]'::jsonb, array['relationship issues', 'cognitive restructuring', 'communication', 'conflict']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('who-i-want-to-be-in-conflict-page', 'Who I Want to Be in Conflict Page', 'act'::resource_kind, 'The client names the qualities they want to show in conflict and a small action for each.', 'Use it to help a client act from values when a conversation gets heated.', array['Adults']::text[], '25 minutes', 'Ask what kind of partner, friend or family member they want to be when things get hard. List qualities and translate each into a concrete behavior. Practice one in session and plan for a recent flashpoint.', '[{"id": "f0", "type": "textarea", "label": "Qualities I want to show in conflict"}, {"id": "f1", "type": "textarea", "label": "What each looks like in action"}, {"id": "f2", "type": "textarea", "label": "A recent conflict where I missed it"}, {"id": "f3", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['relationship issues', 'values', 'conflict', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('repair-after-a-fight-skills-plan', 'Repair After a Fight Skills Plan', 'dbt'::resource_kind, 'The client plans a repair after a fight using validation, an apology where fitting and a request.', 'Use it to help a client reach out after conflict in a way that invites repair.', array['Adults', 'Teens']::text[], '25 minutes', 'Work through what the client wants after the fight, then draft a short message or script with validation, a fitting apology and a clear request. Role-play it. Check if the timing feels right before they send it.', '[{"id": "f0", "type": "textarea", "label": "What happened in the fight"}, {"id": "f1", "type": "textarea", "label": "What I want from the repair"}, {"id": "f2", "type": "textarea", "label": "What I might say, step by step"}, {"id": "f3", "type": "textarea", "label": "When and how I will do it"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'repair', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-the-union-meeting-guide', 'Weekly State of the Union Meeting Guide', 'couples'::resource_kind, 'Partners hold a brief weekly meeting with appreciation, what went well and one issue to work on.', 'Use it to give partners a regular, calm space to talk about the relationship.', array['Couples']::text[], '30 minutes weekly', 'Set a time, a place and a start with appreciations. Then each partner names what went well and one issue. Keep to one issue and use soft startups. End with a plan and a hug if both want one. Review in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciated this week"}, {"id": "f2", "type": "textarea", "label": "The one issue we will work on"}, {"id": "f3", "type": "textarea", "label": "What we agreed to try"}]'::jsonb, array['relationship issues', 'communication', 'Gottman']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('choice-and-control-daily-menu', 'Choice and Control Daily Menu', 'worksheet'::resource_kind, 'The client lists small choices available to them each day and picks a few to practice.', 'Use it to help a client rebuild a sense of choice and control in small daily ways.', array['Adults', 'Teens']::text[], '20 minutes', 'Work from the present only. The client lists everyday choices, from what to wear to who to see, and marks the ones they want to practice. Praise any choice, however small. No details of past events are asked for.', '[{"id": "f0", "type": "textarea", "label": "Small choices I can make today"}, {"id": "f1", "type": "textarea", "label": "Choices I want to practice"}, {"id": "f2", "type": "textarea", "label": "Who respects my choices"}, {"id": "f3", "type": "textarea", "label": "How it felt to choose"}]'::jsonb, array['sexual abuse', 'safety', 'choice', 'stabilization']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('where-responsibility-belongs-reminder-cards', 'Where Responsibility Belongs Reminder Cards', 'cbt'::resource_kind, 'The client writes reminder cards that place responsibility where it belongs, with no need to recount events.', 'Use it to help a client hold steady against self-blame in the present.', array['Adults', 'Teens']::text[], '25 minutes', 'Work in the present: the client writes brief statements to counter self-blame without describing events. Practice reading them aloud. Check if any statement feels untrue and adjust. Offer to pause at any time.', '[{"id": "f0", "type": "textarea", "label": "A self-blame thought that shows up"}, {"id": "f1", "type": "textarea", "label": "A statement that feels true and kind"}, {"id": "f2", "type": "textarea", "label": "Who in my life says kind things like this"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the cards"}]'::jsonb, array['sexual abuse', 'self-blame', 'stabilization', 'cognitive restructuring']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('small-steps-in-my-own-time-values-page', 'Small Steps in My Own Time Values Page', 'act'::resource_kind, 'The client picks values and one tiny action, at a pace that they set and can change at any time.', 'Use it to help a client move toward what matters without being rushed.', array['Adults']::text[], '25 minutes', 'Emphasize that pacing is in the client''s hands. They name values and choose one tiny action to try, with permission to stop. Offer breaks and grounding as needed. No narrative is needed.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me"}, {"id": "f1", "type": "textarea", "label": "One tiny action I could take"}, {"id": "f2", "type": "textarea", "label": "What pace feels right"}, {"id": "f3", "type": "textarea", "label": "What I will do if it feels like too much"}]'::jsonb, array['sexual abuse', 'values', 'pacing', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('soothing-skills-for-body-reminders-menu', 'Soothing Skills for Body Reminders Menu', 'dbt'::resource_kind, 'The client builds a menu of soothing and grounding skills for moments the body feels on alert.', 'Use it to give a client ready steps when the body feels on edge.', array['Adults', 'Teens']::text[], '20 minutes', 'List skills by sense: temperature, textures, scents, sounds, movement. Practice two in session. Let the client decide what is comfortable, and drop anything that does not feel safe. Plan who to contact if needed.', '[{"id": "f0", "type": "textarea", "label": "Skills for my hands and skin"}, {"id": "f1", "type": "textarea", "label": "Skills for sound or scent"}, {"id": "f2", "type": "textarea", "label": "Movement that helps"}, {"id": "f3", "type": "textarea", "label": "People I can reach out to"}]'::jsonb, array['sexual abuse', 'grounding', 'self-soothe', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('support-network-and-pacing-plan', 'Support Network and Pacing Plan', 'worksheet'::resource_kind, 'The client maps people and places that feel safe and plans how fast to share and what to share.', 'Use it to help a client plan support and pacing on their own terms.', array['Adults', 'Teens']::text[], '30 minutes', 'Map supports as circles from closest to more distant and note what the client wants from each. They decide how much to share and when. Call or text 988 appears in the plan for hard nights. Mandatory reporting duties apply if a minor is involved.', '[{"id": "f0", "type": "textarea", "label": "People and places that feel safe"}, {"id": "f1", "type": "textarea", "label": "What I want from each"}, {"id": "f2", "type": "textarea", "label": "What I will share and what I will keep private"}, {"id": "f3", "type": "textarea", "label": "If a night gets very hard I can call or text 988"}]'::jsonb, array['sexual abuse', 'safety', 'support', 'pacing']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('coping-skill-trial-tracker', 'Coping Skill Trial Tracker', 'worksheet'::resource_kind, 'The client tries one skill at a time, rates how it worked and keeps the ones that fit.', 'Use it to help a client find the skills that really work for them.', array['Adults', 'Teens']::text[], 'One week', 'Pick a skill and a situation and ask the client to rate distress before and after. Keep a running page of skills and notes. Retire what does not help without judgment and add what does to a short toolbox.', '[{"id": "f0", "type": "textarea", "label": "Skill I tried"}, {"id": "f1", "type": "textarea", "label": "Situation"}, {"id": "f2", "type": "textarea", "label": "Distress before and after"}, {"id": "f3", "type": "textarea", "label": "Keep, tweak or drop"}]'::jsonb, array['coping skills', 'self-monitoring', 'toolbox']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('if-then-coping-plan-cards', 'If-Then Coping Plan Cards', 'cbt'::resource_kind, 'The client writes if-then cards that link a specific trigger to a chosen coping step.', 'Use it to help a client decide in advance what they will do when stress hits.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick two or three recurring triggers and write if-then plans for each in specific terms. Practice aloud. Keep cards where they can be found quickly and review after a week to see which plans were used.', '[{"id": "f0", "type": "textarea", "label": "Trigger one"}, {"id": "f1", "type": "textarea", "label": "If it happens, then I will"}, {"id": "f2", "type": "textarea", "label": "Trigger two"}, {"id": "f3", "type": "textarea", "label": "If it happens, then I will"}]'::jsonb, array['coping skills', 'planning', 'problem solving']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('choosing-a-skill-that-serves-values-page', 'Choosing a Skill That Serves Values Page', 'act'::resource_kind, 'The client tests whether a coping move moves them toward what they care about or just brings relief.', 'Use it to help a client choose skills with their values in mind.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list moves they use under stress and sort them by whether they bring relief only or also serve what they value. Neither is wrong, but notice costs. Pick one skill to add.', '[{"id": "f0", "type": "textarea", "label": "Moves I use when stressed"}, {"id": "f1", "type": "textarea", "label": "What each gives me in the short run"}, {"id": "f2", "type": "textarea", "label": "What each costs or gives in the long run"}, {"id": "f3", "type": "textarea", "label": "A skill I will add"}]'::jsonb, array['coping skills', 'values', 'workability', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('accepts-distraction-pick-card', 'ACCEPTS Distraction Pick Card', 'dbt'::resource_kind, 'The client chooses distraction skills from the ACCEPTS list and rates each after trying it.', 'Use it to give a client ready distraction ideas for hard moments they cannot change.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through the ACCEPTS list and mark the ones that sound doable. Try one in session. Distraction is for riding out a moment, not for avoiding issues forever, so plan a return to the problem later.', '[{"id": "f0", "type": "textarea", "label": "Distraction skills I like"}, {"id": "f1", "type": "textarea", "label": "One I will try this week"}, {"id": "f2", "type": "textarea", "label": "How it worked"}, {"id": "f3", "type": "textarea", "label": "When I will return to the problem"}]'::jsonb, array['coping skills', 'distress tolerance', 'distraction', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('coping-skills-memory-match-game', 'Coping Skills Memory Match Game', 'game'::resource_kind, 'Players match skill cards with situation cards and explain why the skill fits.', 'Use it to help players link coping skills to real situations.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'Make paired cards, one with a situation and one with a skill. Rules: turn over two cards, make a match, and explain why the skill fits. Scoring is for explanations, not just speed. Debrief on skills players want to try.', '[{"id": "f0", "type": "textarea", "label": "A pair I matched"}, {"id": "f1", "type": "textarea", "label": "Why the skill fits"}, {"id": "f2", "type": "textarea", "label": "A skill I want to try"}, {"id": "f3", "type": "textarea", "label": "A situation I will use it in"}]'::jsonb, array['coping skills', 'group', 'skills']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('fear-rating-step-log', 'Fear Rating Step Log', 'worksheet'::resource_kind, 'The client rates fear on a thermometer across practice steps and notes how it changes.', 'Use it to help a client track how fear changes as they stay with a step.', array['Adults', 'Teens']::text[], 'One week', 'Agree on a rating scale and a practice step. The client records fear before, at peak and after, with notes on what they did. Look at the shape of change together and plan the next step at their pace.', '[{"id": "f0", "type": "textarea", "label": "The practice step"}, {"id": "f1", "type": "textarea", "label": "Fear before and at the peak"}, {"id": "f2", "type": "textarea", "label": "Fear after"}, {"id": "f3", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['phobias', 'exposure', 'fear', 'self-monitoring']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('imagined-versus-actual-outcome-comparison', 'Imagined Versus Actual Outcome Comparison', 'cbt'::resource_kind, 'The client writes what they expect to happen, tests it and compares it with what did happen.', 'Use it to help a client check fearful predictions against real results.', array['Adults', 'Teens']::text[], '25 minutes', 'Before a practice step the client writes the feared outcome and how likely it feels. Afterward they record what happened. Compare the two and discuss what to try next. Gently note outcomes that were better than feared.', '[{"id": "f0", "type": "textarea", "label": "What I expect will happen"}, {"id": "f1", "type": "textarea", "label": "How likely it feels"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'exposure', 'behavioral experiments', 'prediction']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('bringing-fear-along-on-the-climb-page', 'Bringing Fear Along on the Climb Page', 'act'::resource_kind, 'The client takes a step toward something they value with fear coming along instead of waiting for it to leave.', 'Use it to help a client act on values while carrying fear.', array['Adults', 'Teens']::text[], '25 minutes', 'Link a feared situation to something the client wants, such as travel or health care. They name the fear, thank it and decide the step. Practice breathing and noticing. Keep the pace in the client''s hands.', '[{"id": "f0", "type": "textarea", "label": "What I want that fear gets in the way of"}, {"id": "f1", "type": "textarea", "label": "The fear I will bring along"}, {"id": "f2", "type": "textarea", "label": "The step I will take"}, {"id": "f3", "type": "textarea", "label": "How I carried the fear"}]'::jsonb, array['phobias', 'values', 'exposure', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('approach-plan-for-avoided-places', 'Approach Plan for Avoided Places', 'dbt'::resource_kind, 'The client uses opposite action to plan a gradual approach to a place or object they avoid.', 'Use it to help a client plan small approaches instead of avoidance.', array['Adults', 'Teens']::text[], '25 minutes', 'Confirm that the fear is out of step with the actual risk, then plan steps that approach the avoided place or object. Use relaxed breathing and a half smile. Record each step and how the urge to avoid changed.', '[{"id": "f0", "type": "textarea", "label": "The place or thing I avoid"}, {"id": "f1", "type": "textarea", "label": "The urge to avoid and what it says"}, {"id": "f2", "type": "textarea", "label": "Steps of my approach plan"}, {"id": "f3", "type": "textarea", "label": "How the urge changed"}]'::jsonb, array['phobias', 'opposite action', 'exposure', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('brave-steps-sticker-chart-craft', 'Brave Steps Sticker Chart Craft', 'kids'::resource_kind, 'The child decorates a path chart and earns a sticker for each brave step toward something they fear.', 'Use it to help a child and parent track small brave steps.', array['Children']::text[], '30 minutes', 'Draw a winding path with steps and let the child decorate it. Choose very small first steps with the child and parent. Parents give a sticker and warm words for trying, whether or not it went well, and avoid pushing.', '[{"id": "f0", "type": "textarea", "label": "The thing I want to get closer to"}, {"id": "f1", "type": "textarea", "label": "My first brave step"}, {"id": "f2", "type": "textarea", "label": "What my grown-up will say"}, {"id": "f3", "type": "textarea", "label": "How it felt to place the sticker"}]'::jsonb, array['phobias', 'exposure', 'craft', 'parent coaching']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('social-media-feed-body-talk-audit', 'Social Media Feed Body Talk Audit', 'worksheet'::resource_kind, 'The client reviews what their feeds say about bodies and chooses what to keep, mute or add.', 'Use it to help a client shape feeds that feel kinder to how they see themselves.', array['Teens', 'Adults']::text[], '25 minutes', 'Ask the client to scroll their feeds with you and note how each account makes them feel. Choose a few to mute and a few to add. Focus on the feeling, not comparison of bodies. Review how it went after a week.', '[{"id": "f0", "type": "textarea", "label": "Accounts that leave me feeling worse"}, {"id": "f1", "type": "textarea", "label": "Accounts that leave me feeling better"}, {"id": "f2", "type": "textarea", "label": "What I will mute, keep or add"}, {"id": "f3", "type": "textarea", "label": "How my feed feels after a week"}]'::jsonb, array['body image', 'social media', 'self-care']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('body-talk-habits-reframe-page', 'Body Talk Habits Reframe Page', 'cbt'::resource_kind, 'The client notices unkind talk about their body and writes a fairer or neutral reply.', 'Use it to help a client turn down the volume on harsh body talk.', array['Teens', 'Adults']::text[], '25 minutes', 'Collect a few harsh lines the client says about their body and where they happen. Write neutral or kind replies in their voice. Aim for believable rather than glowing. Practice aloud and review which ones stuck.', '[{"id": "f0", "type": "textarea", "label": "A harsh line I say about my body"}, {"id": "f1", "type": "textarea", "label": "When it shows up"}, {"id": "f2", "type": "textarea", "label": "A neutral or kind reply"}, {"id": "f3", "type": "textarea", "label": "Which reply felt most believable"}]'::jsonb, array['body image', 'cognitive restructuring', 'self-compassion']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('body-as-home-not-project-page', 'Body as Home Not Project Page', 'act'::resource_kind, 'The client explores what changes when they treat the body as a home to live in rather than a project to fix.', 'Use it to help a client act on values instead of waiting to feel good about their body.', array['Teens', 'Adults']::text[], '25 minutes', 'Ask the client what they put off until they feel better about their body. Link each to a value and pick one to do now with the thoughts along for the ride. Keep the talk on living, not looks.', '[{"id": "f0", "type": "textarea", "label": "Things I put off because of how I feel about my body"}, {"id": "f1", "type": "textarea", "label": "Values behind them"}, {"id": "f2", "type": "textarea", "label": "One I will do now"}, {"id": "f3", "type": "textarea", "label": "Thoughts that will come along"}]'::jsonb, array['body image', 'values', 'ACT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('kind-action-against-body-avoidance-card', 'Kind Action Against Body Avoidance Card', 'dbt'::resource_kind, 'The client uses opposite action to approach activities they avoid because of body shame.', 'Use it to help a client step toward avoided activities with kindness.', array['Teens', 'Adults']::text[], '20 minutes', 'Name the emotion, such as shame, and its urge to hide. Choose an avoided activity and plan a small step. Add a kind self-statement. Review afterward how the urge to hide shifted and what to try next.', '[{"id": "f0", "type": "textarea", "label": "What I avoid out of shame"}, {"id": "f1", "type": "textarea", "label": "The urge it brings"}, {"id": "f2", "type": "textarea", "label": "The small step I will take"}, {"id": "f3", "type": "textarea", "label": "A kind thing I will say to myself"}]'::jsonb, array['body image', 'opposite action', 'DBT']::text[], '2026-10-20T15:00:00+00:00'::timestamptz),
  ('compliments-beyond-appearance-game', 'Compliments Beyond Appearance Game', 'game'::resource_kind, 'Players trade compliments about character, skills and actions, never appearance.', 'Use it to help a group practice noticing and naming what they value in each other beyond looks.', array['Groups', 'Teens']::text[], '25 minutes', 'Rules: draw a prompt card such as a skill, a kind action or a quality, and give a compliment that fits it to another player. Appearance is off limits. Debrief on how it felt to give and receive such compliments.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "A compliment I received"}, {"id": "f2", "type": "textarea", "label": "What it felt like to leave out appearance"}, {"id": "f3", "type": "textarea", "label": "A quality I want to notice more"}]'::jsonb, array['body image', 'group', 'strengths']::text[], '2026-10-20T15:00:00+00:00'::timestamptz)
